9	/// Runs at most one queued setter or one uncertain-outcome reconciliation.
10	/// The caller is the existing serial Gmail worker; no storage lock is held
11	/// during profile, reconciliation, or setter provider calls.
12	pub(crate) fn run_one(
13	    store: &GmailStore,
14	    provider: &dyn GmailProvider,
15	    cancel: &CancelToken,
16	    policy: SessionPolicy,
17	) -> Result<bool, MailError> {
18	    let Some(record) = store.claim_next_operation()? else {
19	        return Ok(false);
20	    };
21	    if cancel.is_cancelled() {
22	        // A disconnect clears the durable rows after the worker reaches its
23	        // admission barrier. A plain shutdown leaves applying for restart
24	        // recovery, where migration converts it to outcome_unknown.
25	        return Ok(true);
26	    }
27	
28	    let uncertain = record.status == OperationStatus::OutcomeUnknown;
29	    if !uncertain {
30	        require_mutation_access(store, provider, &record)?;
31	    }
32	    let profile = match provider.profile(cancel) {
33	        Ok(profile) => profile,
34	        Err(error) => {
35	            if uncertain {
36	                store.defer_unknown_operation(&record, &error)?;
37	            } else {
38	                store.requeue_operation(&record, &error)?;
39	            }
40	            return Err(error);
41	        }
42	    };
43	    if profile.account_id != record.account_id {
44	        let error = MailError::InvalidRequest {
45	            field: "accountId".to_string(),
46	        };
47	        if uncertain {
48	            store.defer_unknown_operation(&record, &error)?;
49	        } else {
50	            store.fail_operation(&record, error.clone())?;
51	        }
52	        return Err(error);
53	    }
54	
55	    if uncertain {
56	        return reconcile(store, provider, cancel, &record, policy);
57	    }
58	
59	    // The grant may have been revoked between enqueue and dispatch. Check the
60	    // local verified capability again immediately before the setter.
61	    require_mutation_access(store, provider, &record)?;
62	    if cancel.is_cancelled() {
63	        return Ok(true);
64	    }
65	    let result = match record.kind {
66	        MailboxOperationKind::Star => {
67	            provider.apply_star(&record.message_ids, record.value, cancel)
68	        }
69	        MailboxOperationKind::Archive => {
70	            provider.apply_archive(&record.message_ids, record.value, cancel)
71	        }
72	        MailboxOperationKind::Read => {
73	            provider.apply_read(&record.message_ids, record.value, cancel)
74	        }
75	    };
76	    match result {
77	        Ok(()) => store.confirm_operation(&record)?,
78	        Err(MailError::OutcomeUnknown | MailError::AuthCancelled) => {
79	            store.unknown_operation(&record)?;
80	            if !cancel.is_cancelled() {
81	                return reconcile(store, provider, cancel, &record, policy);
82	            }
83	        }
84	        Err(error @ MailError::StorageUnavailable) => return Err(error),
85	        // The production setter uses these two errors only while refreshing a
86	        // token before batchModify; post-dispatch uncertainty is OutcomeUnknown.
87	        Err(
88	            error @ (MailError::NetworkUnavailable
89	            | MailError::ProviderUnavailable
90	            | MailError::InvalidProviderResponse
91	            | MailError::RateLimited
92	            | MailError::AuthRequired
93	            | MailError::PermissionRequired
94	            | MailError::SecretsUnavailable),
95	        ) => {
96	            store.requeue_operation(&record, &error)?;
97	            return Err(error);
98	        }
99	        Err(error) => {
100	            store.fail_operation(&record, error.clone())?;
101	            return Err(error);
102	        }
103	    }
104	    Ok(true)
105	}
106	
107	fn reconcile(
108	    store: &GmailStore,
109	    provider: &dyn GmailProvider,
110	    cancel: &CancelToken,
111	    record: &OperationRecord,
112	    policy: SessionPolicy,
113	) -> Result<bool, MailError> {
114	    let fetched = match provider.get_thread(&record.conversation_id, cancel) {
115	        Ok(Some(thread)) => thread,
116	        Ok(None) => {
117	            store.reconciled_unknown_operation(record)?;
118	            return Ok(true);
119	        }
120	        Err(error) => {
121	            store.defer_unknown_operation(record, &error)?;
122	            return Err(error);
123	        }
124	    };
125	    if fetched.conversation.conversation_ref.account_id != record.account_id
126	        || fetched.conversation.conversation_ref.conversation_id != record.conversation_id
127	    {
128	        store.reconciled_unknown_operation(record)?;
129	        return Ok(true);
130	    }
131	    let all_ids = observed_ids(&fetched);
132	    if !record.message_ids.iter().all(|id| all_ids.contains(id)) {
133	        return finish_unlanded(store, record, &fetched, policy);
134	    }
135	    let matches_all = record.message_ids.iter().all(|id| match record.kind {
136	        MailboxOperationKind::Star => {
137	            fetched.star_facts.as_ref().and_then(|facts| facts.get(id)) == Some(&record.value)
138	        }
139	        MailboxOperationKind::Archive => fetched.inbox_message_ids.contains(id) != record.value,
140	        MailboxOperationKind::Read => fetched
141	            .unread_message_ids
142	            .as_ref()
143	            .is_some_and(|ids| ids.contains(id) != record.value),
144	    });
145	    if matches_all {
146	        store.reconcile_operation(record, &fetched, true)?;
147	        return Ok(true);
148	    }
149	    finish_unlanded(store, record, &fetched, policy)
150	}
151	
152	/// The provider's facts do not show the write. Gmail records the uncertainty;
153	/// a session whose policy allows it requeues the write instead.
154	fn finish_unlanded(
155	    store: &GmailStore,
156	    record: &OperationRecord,
157	    fetched: &GmailThread,
158	    policy: SessionPolicy,
159	) -> Result<bool, MailError> {
160	    if policy.replay_unlanded_interrupted_writes() {
161	        store.requeue_operation(record, &MailError::OutcomeUnknown)?;
162	    } else {
163	        store.reconcile_operation(record, fetched, false)?;
164	    }
165	    Ok(true)
166	}
167	
168	fn require_mutation_access(
169	    store: &GmailStore,
170	    provider: &dyn GmailProvider,
171	    record: &OperationRecord,
172	) -> Result<(), MailError> {
173	    match provider.mutation_access() {
174	        Ok(true) => Ok(()),
175	        Ok(false) => {
176	            store.requeue_operation(record, &MailError::PermissionRequired)?;
177	            Err(MailError::PermissionRequired)
178	        }
179	        Err(error) => {
180	            if error != MailError::StorageUnavailable {
181	                store.requeue_operation(record, &error)?;
182	            }
183	            Err(error)
184	        }
185	    }
186	}
187	
188	fn observed_ids(thread: &GmailThread) -> Vec<String> {
189	    if let Some(ids) = &thread.message_ids {
190	        return ids.clone();
191	    }
192	    let mut ids = thread.inbox_message_ids.clone();
193	    for message in &thread.conversation.messages {
194	        if !ids.contains(&message.id) {
195	            ids.push(message.id.clone());
196	        }
197	    }
198	    ids
199	}
