            MutationAccess::Upgrading
        } else {
            match self.inner.provider.mutation_access() {
                Ok(true) => MutationAccess::Enabled,
                Ok(false) => MutationAccess::ReadOnly,
                Err(capability_error) => {
                    if error.is_none() {
                        error = Some(capability_error);
                    }
                    MutationAccess::ReadOnly
