            provider.writes().is_empty(),
            "a pre-dispatch refresh failure must not reach the fake setter"
        );
        assert!(until(|| core
            .account_status()
            .is_ok_and(
                |status| status.sync.state != mail_core::gmail::types::SyncState::Syncing
